// Typed access to the Go backend (app.go). The bindings under src/bindings
// are generated by `make bindings`; don't edit them by hand.
import { Application, Browser, CancelError, Clipboard, Dialogs, Events } from "@wailsio/runtime"

export * as Backend from "@/bindings/github.com/scg-mitra/sendgrid-template-migration/app"
export type {
  Connection,
  CopyProgress,
  CopyResult,
  Defaults,
  Preview,
  Region,
  Session,
  TemplateInfo,
  UpdateInfo,
} from "@/bindings/github.com/scg-mitra/sendgrid-template-migration/models"
export type { CopyOptions, CopyOverride } from "@/bindings/github.com/scg-mitra/sendgrid-template-migration/models"
export { CopyProgress as CopyProgressEvent } from "@/bindings/events"
export { Application, Browser, Clipboard, Dialogs, Events }

/** The message to show for an error thrown by a backend call. */
export function errorMessage(err: unknown): string {
  if (err instanceof Error) return err.message
  return String(err)
}

/** Whether err is a cancelled backend call (nothing to report). */
export function isCancelled(err: unknown): boolean {
  return err instanceof CancelError
}

/** What to do when the destination already has a template with a copy's name (CopyOptions.onExisting). */
export type ExistingPolicy = "skip" | "add" | "duplicate"

/** What happened to a copied template (CopyResult.action). */
export const CopyAction = { Created: "created", Added: "added", Skipped: "skipped" } as const

/** File dialog filter for template backups. */
export const backupFilter = { DisplayName: "Template backups (*.json)", Pattern: "*.json" }
